def solve_sequence():
    a = {1: 0}
    N = 12  # Calculate up to N=12 to observe the trend

    results = {}

    for n in range(2, N + 1):
        max_val = -1
        best_i = []

        for i in range(1, n):
            # Since a_n is defined using a_i and a_{n-i}, we must have a_i and a_{n-i} already calculated.
            # For i < n/2, n-i > n/2. For i > n/2, n-i < n/2.
            # Since we are iterating i from 1 to n-1, both i and n-i are less than n.

            # The term is a_i + a_{n - i} + min(i, n - i)
            term = a[i] + a[n - i] + min(i, n - i)

            if term > max_val:
                max_val = term
                best_i = [i]
            elif term == max_val:
                best_i.append(i)

        a[n] = max_val
        results[n] = best_i

    return a, results

