def calculate_a(n):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # n = 2k, k = n/2
        k = n // 2
        result = 2 * calculate_a(k) + k
    else:
        # n = 2k+1, k = (n-1)/2
        k = (n - 1) // 2
        # a_n = a_k + a_{k+1} + k
        result = calculate_a(k) + calculate_a(k + 1) + k

    memo[n] = result
    return result

