def calculate_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # n is even: a_n = 2*a_{n/2} + n/2
        result = 2 * calculate_a(n // 2, memo) + n // 2
    else:
        # n is odd: a_n = a_{(n-1)/2} + a_{(n+1)/2} + (n-1)/2
        n_minus_1_div_2 = (n - 1) // 2
        n_plus_1_div_2 = (n + 1) // 2
        result = calculate_a(n_minus_1_div_2, memo) + calculate_a(n_plus_1_div_2, memo) + (n - 1) // 2

    memo[n] = result
    return result

